/* Card set: The Legend of Zelda (generated from zelda.csv by tools/csv-to-set.js schema).
   (zelda.js exceeds the push size limit, so the remaining cards live in zelda-additions.js,
   which must stay directly after 'zelda.js' in sets/manifest.js.) */
CardSets.register({"id":"zelda","name":"The Legend of Zelda","code":"ZELDA","description":"423 cards from the legend of Hyrule — its heroes, sages, monsters, dungeons and treasures, from Link, Princess Zelda and Ganondorf to Epona and the Great Deku Tree. All 21 mainline games included, from the 1986 original to Echoes of Wisdom.","theme":{"primary":"#c9a227","secondary":"#1e4634","artBackground":"#f3ecd9","artFit":"contain"},"pack":{"name":"Zelda Pack","emblem":"🗡","skin":"zelda"},"cards":[{"name":"Link","rarity":"chase","id":"link","subtitle":"Character","details":"The hero reborn across the ages of Hyrule, a swordsman of few words who takes up the Master Sword and the Triforce of Courage whenever darkness rises.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/1/15/TotK_Link_Artwork.png/320px-TotK_Link_Artwork.png"},{"name":"Princess Zelda","rarity":"chase","id":"princess-zelda","subtitle":"Character","details":"Hyrule's princess and bearer of the Triforce of Wisdom, whose bloodline carries the goddess Hylia's power and whose choices shape its fate in every era.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/0/0f/BotW_Zelda_Artwork.png/320px-BotW_Zelda_Artwork.png"},{"name":"Ganondorf","rarity":"chase","id":"ganondorf","subtitle":"Character","details":"The Gerudo king born once a century to his people, wielder of the Triforce of Power whose ambition twists him into the Demon King across Hyrule's history.","image":"assets/sets/compress/zelda__ganondorf.webp"},{"name":"Epona","rarity":"chase","id":"epona","subtitle":"Character","details":"Link's loyal mare from Lon Lon Ranch, summoned by a song played on the ocarina; she carries the hero across Hyrule Field faster than any other horse.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/1/13/OoT_Epona_Artwork.png/512px-OoT_Epona_Artwork.png"},{"name":"Sheik","rarity":"legendary","id":"sheik","subtitle":"Character","details":"A harp-playing Sheikah warrior who appears in Hyrule's ruined future to teach Link the warp songs, hiding the exiled Princess Zelda in a red-eyed disguise.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/e/e5/OoT_Sheik_Artwork.png/512px-OoT_Sheik_Artwork.png"},{"name":"Tetra","rarity":"legendary","id":"tetra","subtitle":"Character","details":"The sharp-tongued pirate captain who sails the Great Sea in search of treasure, unaware her bloodline makes her heir to a drowned kingdom and its Triforce.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/3/32/TWWHD_Tetra_Artwork.png/512px-TWWHD_Tetra_Artwork.png"},{"name":"Midna","rarity":"legendary","id":"midna","subtitle":"Character","details":"The cursed princess of the Twilight Realm, who rides on wolf-form Link's back and trades barbed teasing for a plan to reclaim her stolen throne from Zant.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/b/b6/TPHD_Midna_Artwork.png/512px-TPHD_Midna_Artwork.png"},{"name":"Fi","rarity":"legendary","id":"fi","subtitle":"Character","details":"The spirit dwelling inside the Goddess Sword, who guides her chosen hero with cool, precise analysis and reports the odds of success to the percentage.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/e/ed/SS_Fi_Artwork.png/320px-SS_Fi_Artwork.png"},{"name":"Impa","rarity":"legendary","id":"impa","subtitle":"Character","details":"The Sheikah's faithful servant, guardian and advisor to Hyrule's Royal Family across many eras, from aged keeper of Kakariko to Zelda's sworn protector.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/7/76/OoT_Impa_Artwork.png/512px-OoT_Impa_Artwork.png"},{"name":"Marin","rarity":"legendary","id":"marin","subtitle":"Character","details":"The songstress of Mabe Village on Koholint Island, who dreams of flying beyond the sea and sings the Ballad of the Wind Fish to the island's animals.","image":"https://cdn.wikimg.net/en/zeldawiki/images/2/22/LA_Marin_Artwork.png"},{"name":"Mipha","rarity":"legendary","id":"mipha","subtitle":"Character","details":"The gentle Zora princess and Champion who pilots Divine Beast Vah Ruta, a healer whose grace can mend any wound and whose devotion to Link never wavers.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/f/f0/BotW_Mipha_Artwork.png/512px-BotW_Mipha_Artwork.png"},{"name":"Urbosa","rarity":"legendary","id":"urbosa","subtitle":"Character","details":"The Gerudo chief and Champion who pilots Vah Naboris, a lightning-summoning warrior and old friend of Zelda's mother who treats Zelda as her own.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/c/cf/BotW_Urbosa_Artwork.png/320px-BotW_Urbosa_Artwork.png"},{"name":"Sidon","rarity":"legendary","id":"sidon","subtitle":"Character","details":"The Zora prince whose boundless cheer and flashing smile lift every spirit around him; he stands against Vah Ruta's rains at his sister Mipha's side.","image":"assets/sets/compress/zelda__sidon.webp"},{"name":"King Rauru","rarity":"legendary","id":"king-rauru","subtitle":"Character","details":"The Zonai who founded Hyrule as its first king, a Sage of Light who seals Ganondorf beneath the earth at the cost of his own body in the Imprisoning War.","image":"assets/sets/compress/zelda__king-rauru.webp"},{"name":"Daruk","rarity":"epic","id":"daruk","subtitle":"Character","details":"The Goron Champion who pilots Divine Beast Vah Rudania, a mountain of a warrior whose protective barrier and booming laugh make him Hyrule's big brother.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/f/f3/BotW_Daruk_Artwork.png/512px-BotW_Daruk_Artwork.png"},{"name":"Revali","rarity":"epic","id":"revali","subtitle":"Character","details":"The Rito Champion who pilots Divine Beast Vah Medoh, a master archer of immense pride who perfected his updraft technique to prove himself Hyrule's finest.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/3/31/BotW_Revali_Artwork.png/512px-BotW_Revali_Artwork.png"},{"name":"Riju","rarity":"epic","id":"riju","subtitle":"Character","details":"The young chief of the Gerudo, who rules Gerudo Town from a throne of pillows and walks the desert beside Link wearing the sacred Thunder Helm of Urbosa.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/9/97/TotK_Riju_Artwork.png/512px-TotK_Riju_Artwork.png"},{"name":"Yunobo","rarity":"epic","id":"yunobo","subtitle":"Character","details":"The timid Goron youth descended from Daruk, founder of the YunoboCo mining company, whose rolling charge breaks through rock and marbled corruption alike.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/1/1c/TotK_Yunobo_Artwork.png/320px-TotK_Yunobo_Artwork.png"},{"name":"Tulin","rarity":"epic","id":"tulin","subtitle":"Character","details":"The young Rito warrior whose wind mastery summons a gust that carries Link across the skies; he inherits his father's bow and his courage alike.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/e/ed/TotK_Tulin_Artwork.png/512px-TotK_Tulin_Artwork.png"},{"name":"Mineru","rarity":"epic","id":"mineru","subtitle":"Character","details":"King Rauru's older sister and the Sage of Spirit, a Zonai scholar of constructs who survives into a later age by binding her spirit to a secret stone.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/1/10/TotK_Mineru_Artwork.png/512px-TotK_Mineru_Artwork.png"},{"name":"Queen Sonia","rarity":"epic","id":"queen-sonia","subtitle":"Character","details":"The Hylian cofounder and first queen of Hyrule, a kind ruler gifted with time magic whose marriage to Rauru unites the Zonai and the people of the surface.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/8/89/TotK_Sonia_Model.png/512px-TotK_Sonia_Model.png"},{"name":"Groose","rarity":"epic","id":"groose","subtitle":"Character","details":"The pompadoured Skyloft bully whose jealousy of Link fades into loyalty; he builds the rail-mounted Groosenator that helps hold the Imprisoned at bay.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/d/d4/SS_Groose_Artwork.png/320px-SS_Groose_Artwork.png"},{"name":"Ghirahim","rarity":"epic","id":"ghirahim","subtitle":"Character","details":"The flamboyant Demon Lord who pursues Zelda across the Surface with theatrical menace, seeking to revive his master Demise; his true form is a blade.","image":"assets/sets/compress/zelda__ghirahim.webp"},{"name":"Zant","rarity":"epic","id":"zant","subtitle":"Character","details":"The Usurper King of the Twilight Realm, a desperate Twili who traded his people's freedom for Ganondorf's power and cloaked Hyrule in twilight to claim it.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/9/97/TPHD_Zant_Artwork.png/512px-TPHD_Zant_Artwork.png"},{"name":"Navi","rarity":"epic","id":"navi","subtitle":"Character","details":"The fairy sent by the Great Deku Tree to guide a boy without one, famous across Hyrule for her cries of 'Hey! Listen!' whenever danger or a clue is near.","image":"https://www.zeldadungeon.net/wiki/images/a/ac/Navi.png"},{"name":"Ezlo","rarity":"epic","id":"ezlo","subtitle":"Character","details":"A proud Minish sage cursed into the shape of a green cap, worn by Link through the Minish Cap quest; his grumbling advice comes with the power to shrink.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/2/25/TMC_Ezlo_Artwork.png/512px-TMC_Ezlo_Artwork.png"},{"name":"Linebeck","rarity":"epic","id":"linebeck","subtitle":"Character","details":"The treasure-mad captain of the S.S. Linebeck, a boastful sailor whose cowardice gives way to courage across the seas of the World of the Ocean King.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/b/b8/PH_Linebeck_Artwork.png/512px-PH_Linebeck_Artwork.png"},{"name":"King Daphnes Nohansen Hyrule","rarity":"epic","id":"king-daphnes-nohansen-hyrule","subtitle":"Character","details":"The last king of old Hyrule, bound to the kingdom beneath the Great Sea, who sails beside Link disguised as a talking red boat, the King of Red Lions.","image":"assets/sets/compress/zelda__king-daphnes-nohansen-hyrule.webp"},{"name":"Tatl","rarity":"rare","id":"tatl","subtitle":"Character","details":"The sharp-tongued fairy who joins Link in Termina after her brother Tael stays with the Skull Kid; her jingling chime marks enemies and their weak points.","image":"https://cdn.wikimg.net/en/zeldawiki/images/9/94/MM_Tatl_Artwork.png"},{"name":"Skull Kid","rarity":"rare","id":"skull-kid","subtitle":"Character","details":"A prankster of the Lost Woods who steals Majora's Mask from the Happy Mask Salesman and, possessed by it, drags Termina's moon down toward the carnival.","image":"assets/sets/compress/zelda__skull-kid.webp"},{"name":"Saria","rarity":"rare","id":"saria","subtitle":"Character","details":"Link's childhood friend among the Kokiri and the awakened Sage of Forest, whose song can be heard from anywhere and whose goodbye on the bridge is final.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/0/0f/OoT_Saria_Artwork.png/512px-OoT_Saria_Artwork.png"},{"name":"Darunia","rarity":"rare","id":"darunia","subtitle":"Character","details":"The patriarch of the Gorons and awakened Sage of Fire, a lover of music and dance who names Link his Sworn Brother after the Dodongo's Cavern is cleared.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/d/d3/OoT_Darunia_Artwork.png/512px-OoT_Darunia_Artwork.png"},{"name":"Princess Ruto","rarity":"rare","id":"princess-ruto","subtitle":"Character","details":"The headstrong Zora princess and awakened Sage of Water, who as a child rides through Lord Jabu-Jabu's belly in Link's arms and calls it an engagement.","image":"https://cdn.wikimg.net/en/zeldawiki/images/3/39/OoT3D_Princess_Ruto_Model.png"},{"name":"Nabooru","rarity":"rare","id":"nabooru","subtitle":"Character","details":"The Gerudo's second-in-command and awakened Sage of Spirit, a lone thief who opposes Ganondorf from inside his own tribe and pays for it with her freedom.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/1/1e/OoT_Nabooru_Artwork.png/512px-OoT_Nabooru_Artwork.png"},{"name":"Medli","rarity":"rare","id":"medli","subtitle":"Character","details":"The Rito attendant of Dragon Roost Island and descendant of the Earth Sage, whose harp carries the Earth God's Lyric into the Earth Temple beneath the sea.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/c/cf/TWWHD_Medli_Artwork.png/512px-TWWHD_Medli_Artwork.png"},{"name":"Makar","rarity":"rare","id":"makar","subtitle":"Character","details":"The small Korok violinist of the Forbidden Woods and descendant of the Wind Sage, whose leafy fiddle carries the Wind God's Aria into the Wind Temple.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/9/9a/TWWHD_Makar_Artwork.png/512px-TWWHD_Makar_Artwork.png"},{"name":"Aryll","rarity":"rare","id":"aryll","subtitle":"Character","details":"Link's little sister of Outset Island, a lover of seagulls whose kidnapping by the Helmaroc King sets her brother's voyage across the Great Sea in motion.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/0/08/TWWHD_Aryll_Artwork.png/512px-TWWHD_Aryll_Artwork.png"},{"name":"Tingle","rarity":"rare","id":"tingle","subtitle":"Character","details":"The 35-year-old map seller in green tights who believes himself a forest fairy's reincarnation, charging whatever the market bears for his charts.","image":"assets/sets/compress/zelda__tingle.webp"},{"name":"Agahnim","rarity":"rare","id":"agahnim","subtitle":"Character","details":"The robed wizard who seizes Hyrule Castle, dissolves the Sages' seal and sends the maidens of the Sages' line into the Dark World in A Link to the Past.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/2/24/ALttP_Agahnim_Artwork.png/512px-ALttP_Agahnim_Artwork.png"},{"name":"Vaati","rarity":"rare","id":"vaati","subtitle":"Character","details":"A Minish apprentice turned wind sorcerer, drunk on the Light Force he stole from Princess Zelda, whose schemes trouble Hyrule across the Four Swords tales.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/5/5a/TMC_Vaati_Artwork.png/512px-TMC_Vaati_Artwork.png"},{"name":"Laruto","rarity":"rare","id":"laruto","subtitle":"Character","details":"The Zora Earth Sage of sunken Hyrule, slain by Ganondorf's servants, whose spirit appears in the Earth Temple to teach Medli the Earth God's Lyric.","image":"assets/sets/compress/zelda__laruto.webp"},{"name":"Princess Hilda","rarity":"rare","id":"princess-hilda","subtitle":"Character","details":"The princess of Lorule, Hyrule's crumbling mirror kingdom, who schemes to steal a neighbouring world's Triforce to save her own fading, fissured realm.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/8/8f/ALBW_Princess_Hilda_Artwork.png/512px-ALBW_Princess_Hilda_Artwork.png"},{"name":"Ravio","rarity":"rare","id":"ravio","subtitle":"Character","details":"The hooded merchant in a bunny hood who rents adventuring gear from his shop in Link's own house, and whose diary reveals a coward's heart from Lorule.","image":"https://cdn.wikimg.net/en/zeldawiki/images/c/ce/ALBW_Ravio_Model.png"},{"name":"Yuga","rarity":"rare","id":"yuga","subtitle":"Character","details":"The flamboyant sorcerer of Lorule who turns Hyrule's Sages into paintings to revive Ganon, then merges with the Demon King to seize the Triforce of Power.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/a/a6/ALBW_Yuga_Artwork.png/512px-ALBW_Yuga_Artwork.png"},{"name":"Purah","rarity":"rare","id":"purah","subtitle":"Character","details":"The Sheikah researcher who directs ancient tech studies from her labs, developer of the Purah Pad and an expert on the Guidance Stones and the Upheaval.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/9/9b/TotK_Purah_Artwork.png/512px-TotK_Purah_Artwork.png"},{"name":"Kass","rarity":"rare","id":"kass","subtitle":"Character","details":"The wandering Rito bard who travels Hyrule playing his teacher's songs on the accordion, passing ancient verses about the hero to those who listen.","image":"assets/sets/compress/zelda__kass.webp"},{"name":"Hestu","rarity":"rare","id":"hestu","subtitle":"Character","details":"The giant, maraca-shaking Korok musician who expands Link's stashes in exchange for Korok Seeds, forever losing his maracas somewhere along the road.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/b/b0/TotK_Hestu_Artwork.png/512px-TotK_Hestu_Artwork.png"},{"name":"Tri","rarity":"rare","id":"tri","subtitle":"Character","details":"The small, mysterious being who lends Princess Zelda the Tri Rod in Echoes of Wisdom, creating echoes of tables, beds and monsters to mend the rifts.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/6/6f/EoW_Tri_Model.png/320px-EoW_Tri_Model.png"},{"name":"Great Deku Tree","rarity":"rare","id":"great-deku-tree","subtitle":"Character","details":"The guardian tree of the forest, father of the Kokiri and later the Koroks, who shelters the Master Sword's clearing and speaks with the earth itself.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/6/67/OoT_Great_Deku_Tree_Artwork.png/320px-OoT_Great_Deku_Tree_Artwork.png"},{"name":"Malon","rarity":"uncommon","id":"malon","subtitle":"Character","details":"The cheerful ranch girl of Lon Lon Ranch who teaches Link Epona's Song, cares for the horses, and delivers milk from her family's ranch to Hyrule Castle.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/2/28/OoT_Malon_Artwork.png/512px-OoT_Malon_Artwork.png"},{"name":"Talon","rarity":"uncommon","id":"talon","subtitle":"Character","details":"The sleep-loving owner of Lon Lon Ranch and Malon's father, a moustached rancher who naps anywhere, races cuccos, and resembles a certain plumber.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/f/f7/OoT_Talon_Artwork.png/512px-OoT_Talon_Artwork.png"},{"name":"Kaepora Gaebora","rarity":"uncommon","id":"kaepora-gaebora","subtitle":"Character","details":"The great owl who watches over Hyrule and offers Link long guidance from rooftops and desert ruins — and asks if you got all that, every single time.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/c/c4/OoT_Kaepora_Gaebora_Artwork.png/512px-OoT_Kaepora_Gaebora_Artwork.png"},{"name":"Prince Komali","rarity":"uncommon","id":"prince-komali","subtitle":"Character","details":"The shy Rito prince of Dragon Roost Island, son of the chieftain, who must climb the island's cavern to earn his wings from Valoo and find his courage.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/8/84/TWWHD_Komali_Artwork.png/512px-TWWHD_Komali_Artwork.png"},{"name":"Anju","rarity":"uncommon","id":"anju","subtitle":"Character","details":"The innkeeper of Clock Town's Stock Pot Inn, whose missing fiancé Kafei vanished before their wedding; their reunion is Termina's longest love story.","image":"assets/sets/compress/zelda__anju.webp"},{"name":"Kafei","rarity":"uncommon","id":"kafei","subtitle":"Character","details":"Clock Town's missing groom, cursed into a child's form by the Skull Kid, who hides at the Laundry Pool and works with Link to reclaim his Sun's Mask.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/1/11/MM_Kafei_Artwork.png/512px-MM_Kafei_Artwork.png"},{"name":"Happy Mask Salesman","rarity":"uncommon","id":"happy-mask-salesman","subtitle":"Character","details":"The mask collector with an unnerving smile who follows Link across Hyrule and Termina, teaching the Song of Healing and demanding his stolen mask back.","image":"assets/sets/compress/zelda-additions__song-of-healing.webp"},{"name":"Romani","rarity":"uncommon","id":"romani","subtitle":"Character","details":"The young girl of Romani Ranch who recruits Link to defend the barn against 'Them' — the ghostly raiders who come for the cows before the carnival dawn.","image":"https://cdn.wikimg.net/en/zeldawiki/images/1/15/MM3D_Romani_Model.png"},{"name":"Din","rarity":"uncommon","id":"din","subtitle":"Character","details":"The Oracle of Seasons, a dancer of Holodrum whose capture by General Onox throws the seasons into chaos, freezing spring and scorching summer out of turn.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/6/62/OoS_Din_Artwork.png/512px-OoS_Din_Artwork.png"},{"name":"Nayru","rarity":"uncommon","id":"nayru","subtitle":"Character","details":"The Oracle of Ages, a singer of Labrynna whose body is possessed by Veran, twisting the past to build a tower of sorrow that reaches into the present age.","image":"assets/sets/compress/zelda__nayru.webp"},{"name":"Ralph","rarity":"uncommon","id":"ralph","subtitle":"Character","details":"The brash, red-headed grandson of the Maku Tree's protector line in Labrynna, who charges headlong after Veran to save Nayru despite having no chance.","image":"https://cdn.wikimg.net/en/zeldawiki/images/c/cb/OoA_Ralph_Artwork.png"},{"name":"Queen Ambi","rarity":"uncommon","id":"queen-ambi","subtitle":"Character","details":"The queen of Labrynna in its past, builder of the Black Tower and lover of a lost sea captain, whose endless construction shapes two eras of her kingdom.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/2/24/OoA_Queen_Ambi_Artwork.png/512px-OoA_Queen_Ambi_Artwork.png"},{"name":"Beedle","rarity":"uncommon","id":"beedle","subtitle":"Character","details":"The travelling merchant who sells his wares from ships and balloons and storefronts across the Great Sea and Hyrule, crying 'Thank you!' at every sale.","image":"assets/sets/compress/zelda__beedle.webp"},{"name":"Grandma","rarity":"uncommon","id":"grandma","subtitle":"Character","details":"Link's grandmother of Outset Island, who sends Link off in the hero's green clothes and brews an elixir soup so good it counts as two servings in one.","image":"assets/sets/compress/zelda__grandma.webp"},{"name":"Orca","rarity":"uncommon","id":"orca","subtitle":"Character","details":"The retired swordsman of Outset Island who teaches Link the blade, from the spin attack to the hurricane spin, and weeps with pride at a master's form.","image":"assets/sets/compress/zelda__orca.webp"},{"name":"Ilia","rarity":"uncommon","id":"ilia","subtitle":"Character","details":"The Ordon Village girl who cares for Epona as tenderly as her own family, whose kidnapping by Bulblins draws Link's village into Hyrule's twilight crisis.","image":"https://cdn.wikimg.net/en/zeldawiki/images/e/eb/TP_Ilia_Model.png"},{"name":"Telma","rarity":"uncommon","id":"telma","subtitle":"Character","details":"The Hyrule Castle Town barkeeper who shelters the Resistance, arranges transport for the wounded and drives a covered wagon through monster country.","image":"assets/sets/compress/zelda__telma.webp"},{"name":"Agitha","rarity":"uncommon","id":"agitha","subtitle":"Character","details":"The self-styled Princess of the Insect Kingdom in Castle Town, who hosts a ball for golden bugs and pays handsomely for every male and female pair.","image":"assets/sets/compress/zelda__agitha.webp"},{"name":"Ciela","rarity":"uncommon","id":"ciela","subtitle":"Character","details":"The amnesiac fairy who joins Link at sea and is revealed as the Spirit of Time and Courage, her true power the key to stopping Bellum on the Ghost Ship.","image":"https://cdn.wikimg.net/en/zeldawiki/images/d/d9/PH_Ciela_Artwork.png"},{"name":"Anjean","rarity":"uncommon","id":"anjean","subtitle":"Character","details":"The wise Lokomo elder who keeps the Tower of Spirits in Spirit Tracks, a friend of Tetra's who guides Zelda and Link in restoring the kingdom's railways.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/3/3b/ST_Anjean_Artwork.png/512px-ST_Anjean_Artwork.png"},{"name":"Byrne","rarity":"uncommon","id":"byrne","subtitle":"Character","details":"The warrior in a clawed gauntlet who serves Chancellor Cole hoping to be made a spirit, and turns against his master when the betrayal is revealed.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/a/a9/ST_Byrne_Artwork.png/512px-ST_Byrne_Artwork.png"},{"name":"Chancellor Cole","rarity":"uncommon","id":"chancellor-cole","subtitle":"Character","details":"The two-hatted chancellor of New Hyrule, a demon in disguise who schemes to free the Demon King Malladus and steal Princess Zelda's body as his new vessel.","image":"https://cdn.wikimg.net/en/zeldawiki/images/f/f5/ST_Cole_Artwork.png"},{"name":"Gaepora","rarity":"uncommon","id":"gaepora","subtitle":"Character","details":"The headmaster of Skyloft's Knight Academy and father of Zelda, overseer of the Wing Ceremony whose name echoes an old sage of Hyrule's distant past.","image":"assets/sets/compress/zelda__gaepora.webp"},{"name":"Sahasrahla","rarity":"uncommon","id":"sahasrahla","subtitle":"Character","details":"The elder of Kakariko Village and descendant of the Seven Sages in A Link to the Past, who sends Link to the Eastern Palace and warns of the Moon Pearl.","image":"https://cdn.wikimg.net/en/zeldawiki/images/e/ec/ALttP_Sahasrahla_Artwork.png"},{"name":"Old Man","rarity":"uncommon","id":"old-man","subtitle":"Character","details":"The cave dweller of Hyrule's wilderness who hands a lone hero a sword with the warning 'It's dangerous to go alone! Take this' — the series' first gift.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/2/2b/TLoZ_Old_Man_Artwork.png/320px-TLoZ_Old_Man_Artwork.png"},{"name":"Error","rarity":"uncommon","id":"error","subtitle":"Character","details":"A resident of Zelda II's Ruto Town known to every traveller for a single famous introduction — 'I AM ERROR' — and almost nothing else in the adventure.","image":"https://cdn.wikimg.net/en/zeldawiki/images/c/ce/TAoL_Error_Sprite.png"},{"name":"Tarin","rarity":"uncommon","id":"tarin","subtitle":"Character","details":"Marin's mushroom-loving father in Mabe Village, a hunter who once transformed into a raccoon after eating the wrong toadstool in the Mysterious Woods.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/4/4b/LA_Tarin_Artwork.png/320px-LA_Tarin_Artwork.png"},{"name":"Paya","rarity":"uncommon","id":"paya","subtitle":"Character","details":"The shy Sheikah of Kakariko Village, granddaughter of Impa, whose diary betrays her flustered admiration for the hero she serves tea and timid directions.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/1/19/TotK_Paya_Artwork.png/512px-TotK_Paya_Artwork.png"},{"name":"Robbie","rarity":"uncommon","id":"robbie","subtitle":"Character","details":"The eccentric Sheikah researcher of the Akkala Ancient Tech Lab, a goggles-wearing inventor who builds ancient arrows and armour in exchange for materials.","image":"https://cdn.wikimg.net/en/zeldawiki/images/b/bd/TotK_Robbie_Artwork.png"},{"name":"Teba","rarity":"uncommon","id":"teba","subtitle":"Character","details":"The proud Rito warrior who storms Divine Beast Vah Medoh alongside Link, a father and archer whose village-first stubbornness hides a protective heart.","image":"assets/sets/compress/zelda__teba.webp"},{"name":"Penn","rarity":"uncommon","id":"penn","subtitle":"Character","details":"The Rito reporter for the Lucky Clover Gazette who chases scoops across Hyrule with his partner Traysi, investigating rumours of Zelda's appearances.","image":"https://cdn.wikimg.net/en/zeldawiki/images/0/03/TotK_Penn_Model.png"},{"name":"Irene","rarity":"common","id":"irene","subtitle":"Character","details":"The apprentice witch who ferries Link across Hyrule by broom and bell in A Link Between Worlds, one of the seven Sages hidden in a green-robed disguise.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/6/6e/ALBW_Irene_Artwork.png/512px-ALBW_Irene_Artwork.png"},{"name":"Seres","rarity":"common","id":"seres","subtitle":"Character","details":"The kind daughter of the Sanctuary priest and one of Hyrule's seven Sages in A Link Between Worlds, first of the maidens Yuga turns into a living painting.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/9/9c/ALBW_Seres_Artwork.png/512px-ALBW_Seres_Artwork.png"},{"name":"Link's Uncle","rarity":"common","id":"links-uncle","subtitle":"Character","details":"The swordsman who answers Hyrule Castle's call on a stormy night in A Link to the Past, falling in its secret passage and passing his sword to his nephew.","image":"https://cdn.wikimg.net/en/zeldawiki/images/f/ff/ALttP_Link%27s_Uncle_Artwork.png"},{"name":"Madam MeowMeow","rarity":"common","id":"madam-meowmeow","subtitle":"Character","details":"The Mabe Village cat lover whose pampered pet Chain Chomp, BowWow, becomes Link's unlikely dungeon companion after a dognapping rescue from the moblins.","image":"https://cdn.wikimg.net/en/zeldawiki/images/9/96/LANS_Madam_MeowMeow_Model.png"},{"name":"Mr. Write","rarity":"common","id":"mr-write","subtitle":"Character","details":"The letter-writing recluse of Goponga Swamp in Link's Awakening, who treasures a photo sent by his pen pal Christine — who is, in truth, a literate goat.","image":"https://cdn.wikimg.net/en/zeldawiki/images/4/43/LA_Mr._Write_Artwork.png"},{"name":"Crazy Tracy","rarity":"common","id":"crazy-tracy","subtitle":"Character","details":"The potion seller of Koholint's swamp in Link's Awakening, whose secret medicine revives a fallen hero and whose prices shift with her unpredictable moods.","image":"https://cdn.wikimg.net/en/zeldawiki/images/9/98/LANS_Tracy_Model.png"},{"name":"Prince Richard","rarity":"common","id":"prince-richard","subtitle":"Character","details":"A prince living at Villa Richard among his frogs in Link's Awakening, a cameo swordsman who trades the path to the Key Cavern for five golden leaves.","image":"https://cdn.wikimg.net/en/zeldawiki/images/9/95/LA_Prince_Richard_Artwork.png"},{"name":"Smith","rarity":"common","id":"smith","subtitle":"Character","details":"The master swordsmith of Hyrule Town in The Minish Cap, grandfather of Link, whose forge makes the White Sword and whose king's commission opens the story.","image":"https://cdn.wikimg.net/en/zeldawiki/images/b/bd/TMC_Smith_Sprite.png"},{"name":"King Daltus","rarity":"common","id":"king-daltus","subtitle":"Character","details":"The king of Hyrule in The Minish Cap and father of Princess Zelda, turned to stone by Vaati's curse at the Picori Festival's sword ceremony in Hyrule Town.","image":"https://cdn.wikimg.net/en/zeldawiki/images/2/23/TMC_King_Daltus_Sprite.png"},{"name":"Oshus","rarity":"common","id":"oshus","subtitle":"Character","details":"The elder of Mercay Island who shelters Link after a shipwreck, revealed in time as the Ocean King himself, weakened by Bellum's stolen life force.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/8/82/PH_Oshus_Artwork.png/512px-PH_Oshus_Artwork.png"},{"name":"Jolene","rarity":"common","id":"jolene","subtitle":"Character","details":"The pirate captain who duels Link at every meeting over a grudge with Linebeck, crossing blades across the seas while her former friend hides in a crate.","image":"https://cdn.wikimg.net/en/zeldawiki/images/7/76/PH_Jolene_Model.png"},{"name":"Colin","rarity":"common","id":"colin","subtitle":"Character","details":"The Ordon Village boy who idolises Link in Twilight Princess, whose courage in shielding Beth at Kakariko marks his growth into his father's resolve.","image":"assets/sets/compress/zelda__colin.webp"},{"name":"Barnes","rarity":"common","id":"barnes","subtitle":"Character","details":"The bomb shopkeeper of Kakariko Village in Twilight Princess, whose singed afro and twitching nerves come from a lifetime of selling things that explode.","image":"assets/sets/compress/zelda__barnes.webp"},{"name":"Renado","rarity":"common","id":"renado","subtitle":"Character","details":"The shaman of Kakariko Village in Twilight Princess, a healer who shelters Ordon's stolen children and helps restore Ilia's lost memory with old wisdom.","image":"assets/sets/compress/zelda__renado.webp"},{"name":"Scrapper","rarity":"common","id":"scrapper","subtitle":"Character","details":"An ancient, sharp-tongued robot of the Lanayru robots in Skyward Sword, who hauls heavy cargo for 'Master Shortpants' while insulting him the entire way.","image":"https://www.zeldadungeon.net/wiki/images/d/d3/Scrapper.jpg"},{"name":"Gorko","rarity":"common","id":"gorko","subtitle":"Character","details":"The Goron archaeologist who roams the Surface in Skyward Sword researching Goddess Walls and Goddess Cubes, always thrilled by a new find.","image":"assets/sets/compress/zelda__gorko.webp"},{"name":"Strich","rarity":"common","id":"strich","subtitle":"Character","details":"A Skyloft knight-in-training and obsessive insect collector in Skyward Sword, who buys Link's spare bugs and runs the Bug Heaven game on a floating island.","image":"https://cdn.wikimg.net/en/zeldawiki/images/5/59/SSHD_Strich_Model.png"},{"name":"Kilton","rarity":"common","id":"kilton","subtitle":"Character","details":"The monster enthusiast who opens his Fang and Bone shop by night across Hyrule, trading in a currency of his own invention — mon, paid for monster parts.","image":"https://www.zeldadungeon.net/wiki/images/0/0d/TotK-Kilton.png"},{"name":"Bolson","rarity":"common","id":"bolson","subtitle":"Character","details":"The flamboyant head of Bolson Construction in Hateno Village, whose signature dance and love of round-cornered houses define his company's building style.","image":"https://www.zeldadungeon.net/wiki/images/6/66/Bolson.jpg"},{"name":"Hudson","rarity":"common","id":"hudson","subtitle":"Character","details":"The Bolson Construction builder who founds Tarrey Town plank by plank in Breath of the Wild, then raises Hudson Construction across Hyrule with his family.","image":"https://www.zeldadungeon.net/wiki/images/2/2e/Hudson.png"},{"name":"Josha","rarity":"common","id":"josha","subtitle":"Character","details":"The young Sheikah prodigy who heads Depths research at Lookout Landing, directing the Zonai Survey Team's chasm investigations beneath Hyrule's surface.","image":"https://cdn.wikimg.net/en/zeldawiki/images/3/3a/TotK_Josha_Artwork.png"},{"name":"Tauro","rarity":"common","id":"tauro","subtitle":"Character","details":"The shirtless leader of the Zonai Survey Team, a scholar of ruins and murals who deciphers Zonai script across Hyrule's ring ruins and forgotten temples.","image":"assets/sets/compress/zelda__tauro.webp"},{"name":"Lueburry","rarity":"common","id":"lueburry","subtitle":"Character","details":"The Sheikah researcher of Echoes of Wisdom, older brother of Impa, who studies the rifts tearing Hyrule from his house on the edge of Suthorn Village.","image":"assets/sets/compress/zelda__lueburry.webp"},{"name":"Condé","rarity":"common","id":"cond","subtitle":"Character","details":"The gentle yeti-like resident of Hebra Mountain in Echoes of Wisdom, who shelters Zelda from the snow and waits for his older brother's return home.","image":"https://cdn.wikimg.net/en/zeldawiki/images/5/54/EoW_Cond%C3%A9_Model.png"},{"name":"Minister Lefte","rarity":"common","id":"minister-lefte","subtitle":"Character","details":"The left-hand minister of Hyrule's king in Echoes of Wisdom, a studious official who examines the mysterious rifts spreading across the kingdom's lands.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/d/db/EoW_Minister_Lefte_Model.png/512px-EoW_Minister_Lefte_Model.png"},{"name":"General Wright","rarity":"common","id":"general-wright","subtitle":"Character","details":"The right-hand general of Hyrule's army in Echoes of Wisdom, a dutiful commander who leads soldiers against the rifts and the impostors seizing the throne.","image":"assets/sets/compress/zelda__general-wright.webp"},{"name":"Ingo","rarity":"common","id":"ingo","subtitle":"Character","details":"The bitter Lon Lon Ranch hand in Ocarina of Time who schemes to deliver Epona to Ganondorf, briefly running the ranch as a rigged horse-racing business.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/b/ba/OoT_Ingo_Artwork.png/512px-OoT_Ingo_Artwork.png"},{"name":"King Zora","rarity":"common","id":"king-zora","subtitle":"Character","details":"The monarch of Zora's Domain in Ocarina of Time and father of Princess Ruto, whose inch-by-inch slide aside is the series' slowest royal audience.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/2/2b/OoT_King_Zora_Artwork.png/512px-OoT_King_Zora_Artwork.png"},{"name":"Cremia","rarity":"common","id":"cremia","subtitle":"Character","details":"Romani's older sister and keeper of Romani Ranch, who runs the hazardous milk delivery to Clock Town through masked bandits on the road's final night.","image":"https://cdn.wikimg.net/en/zeldawiki/images/3/3f/MM3D_Cremia_Model.png"},{"name":"Tael","rarity":"common","id":"tael","subtitle":"Character","details":"Tatl's fairy brother, who stays at the Skull Kid's side in Termina and, at the last hour, points the way to the Four Giants who can save Termina.","image":"https://cdn.wikimg.net/en/zeldawiki/images/c/c5/MM_Tael_Artwork.png"},{"name":"Postman","rarity":"common","id":"postman","subtitle":"Character","details":"The tireless letter carrier of Termina and Hyrule, whose delivery schedule, bunny hood speed and devotion to the mail survive even the end of the world.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/c/cf/MM_Postman_Artwork.png/512px-MM_Postman_Artwork.png"},{"name":"Guru-Guru","rarity":"common","id":"guru-guru","subtitle":"Character","details":"The windmill organ-grinder forever playing the Song of Storms, furious at the boy who once played it in his mill and taught the storm to the sky.","image":"https://cdn.wikimg.net/en/zeldawiki/images/4/4d/OoS_Guru-Guru_Artwork.png"},{"name":"Dampé","rarity":"common","id":"damp","subtitle":"Character","details":"The hook-nosed gravekeeper of Kakariko Graveyard, whose grave-digging tour and posthumous races reward the patient visitor to his damp crypt.","image":"https://cdn.wikimg.net/en/zeldawiki/images/1/1d/OoT_Damp%C3%A9_Model.png"},{"name":"Maple","rarity":"common","id":"maple","subtitle":"Character","details":"The apprentice witch of the Oracle games who crashes into Link by broomstick, dropping her potions in a scramble both travellers race to collect first.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/b/b9/OoS_Maple_Artwork.png/512px-OoS_Maple_Artwork.png"},{"name":"Syrup","rarity":"common","id":"syrup","subtitle":"Character","details":"The potion-brewing witch whose hut appears in the Oracle games and The Minish Cap, selling syrups and secrets from behind a cauldron and a knowing grin.","image":"assets/sets/compress/zelda__syrup.webp"},{"name":"Madame Couture","rarity":"common","id":"madame-couture","subtitle":"Character","details":"The designer of Hytopia in Tri Force Heroes, whose ability-granting outfits — sewn from materials heroes gather — are the kingdom's answer to adventure.","image":"https://cdn.wikimg.net/en/zeldawiki/images/a/a0/TFH_Madame_Couture_Artwork.png"},{"name":"Farore","rarity":"common","id":"farore","subtitle":"Character","details":"The Oracle of Secrets in the Oracle games, keeper of the Hall of Secrets inside the Maku Tree, who records the passwords linking two quests into one tale.","image":"assets/sets/compress/zelda__farore.webp"},{"name":"Sakon","rarity":"common","id":"sakon","subtitle":"Character","details":"The grinning thief who robs travellers around Termina, steals the Sun's Mask from Kafei, and hides his loot behind a rockfall in Ikana Canyon.","image":"https://cdn.wikimg.net/en/zeldawiki/images/d/d7/MM3D_Sakon_Model.png"},{"name":"Darmani","rarity":"common","id":"darmani","subtitle":"Character","details":"The fallen Goron hero of Snowhead, whose spirit lingers at his grave until the Song of Healing grants him rest and Link the Goron Mask with his strength.","image":"assets/sets/compress/zelda__darmani.webp"},{"name":"Mikau","rarity":"common","id":"mikau","subtitle":"Character","details":"The Zora guitarist of the Indigo-Go's, washed ashore dying at Great Bay, whose spirit entrusts Link with the Zora Mask and one last performance for Lulu.","image":"https://cdn.wikimg.net/en/zeldawiki/images/1/12/MM_Mikau_Artwork.png"},{"name":"Hyrule Castle","rarity":"chase","id":"hyrule-castle","subtitle":"Location","details":"Hyrule's royal seat towers over the kingdom in age after age, its throne room, towers and hidden passages serving as a final battleground.","image":"assets/sets/compress/zelda__hyrule-castle.webp"},{"name":"Temple of Time","rarity":"legendary","id":"temple-of-time","subtitle":"Location","details":"This sacred temple guards the Door of Time and the Master Sword's pedestal, linking the Sacred Realm to the hero chosen to draw the blade.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/b/b3/OoT3D_Temple_of_Time_Interior.png/320px-OoT3D_Temple_of_Time_Interior.png"},{"name":"Clock Town","rarity":"legendary","id":"clock-town","subtitle":"Location","details":"Termina's busy hub spreads around its great clock tower in four districts, counting down three days to the Carnival of Time beneath a falling moon.","image":"https://cdn.wikimg.net/en/zeldawiki/images/d/d2/MM3D_South_Clock_Town.png"},{"name":"Skyloft","rarity":"legendary","id":"skyloft","subtitle":"Location","details":"A village of wooden walkways floats above the cloud barrier, home to the Knight Academy, the Statue of the Goddess and riders of Loftwings.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/f/f8/SSHD_Skyloft.png/320px-SSHD_Skyloft.png"},{"name":"Great Plateau","rarity":"legendary","id":"great-plateau","subtitle":"Location","details":"Cliff-ringed highland above Hyrule's plains, holding the Shrine of Resurrection, the ruined Temple of Time and the kingdom's ancient heart.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/7/74/BotW_Great_Plateau.png/320px-BotW_Great_Plateau.png"},{"name":"Death Mountain","rarity":"legendary","id":"death-mountain","subtitle":"Location","details":"A smoking volcanic peak sacred to the Gorons, its crater trails are lined with lava flows, falling rock, mines and fireproof elixirs alike.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/7/79/BotW_Death_Mountain.png/320px-BotW_Death_Mountain.png"},{"name":"Palace of Twilight","rarity":"legendary","id":"palace-of-twilight","subtitle":"Dungeon","details":"The Royal Palace of the Twilight Realm drapes its bridges and courtyards in black and gold, seat of a throne seized by the usurper Zant.","image":"assets/sets/compress/zelda__palace-of-twilight.webp"},{"name":"Kakariko Village","rarity":"epic","id":"kakariko-village","subtitle":"Location","details":"A quiet village tucked below Death Mountain, tied to the Sheikah, a graveyard of royal tombs, wells, windmills and secrets kept for generations.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/b/b2/BotW_Kakariko_Village.png/320px-BotW_Kakariko_Village.png"},{"name":"Kokiri Forest","rarity":"epic","id":"kokiri-forest","subtitle":"Location","details":"A sunlit clearing village where Kokiri children live under fairy partners and the Great Deku Tree, never ageing while the forest protects them.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/2/2d/OoT3D_Kokiri_Forest.png/320px-OoT3D_Kokiri_Forest.png"},{"name":"Zora's Domain","rarity":"epic","id":"zoras-domain","subtitle":"Location","details":"A luminous waterfall city carved into cliffs at the head of Zora's River, built around a throne hall, a diving game and ever-flowing water.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/0/06/TP_Zora%27s_Domain.jpg/320px-TP_Zora%27s_Domain.jpg"},{"name":"Gerudo Valley","rarity":"epic","id":"gerudo-valley","subtitle":"Location","details":"A sun-baked canyon split by a deep gorge and great bridge, forming the guarded gateway between Hyrule Field and the Gerudo desert beyond it.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/8/85/OoT_Gerudo_Valley.png/512px-OoT_Gerudo_Valley.png"},{"name":"Windfall Island","rarity":"epic","id":"windfall-island","subtitle":"Location","details":"A bustling Great Sea port built around a market square, school, lighthouse wheel and Pictograph shop, where sailors trade news and treasure.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/0/0c/TWWHD_Windfall_Island.png/320px-TWWHD_Windfall_Island.png"},{"name":"Castle Town","rarity":"epic","id":"castle-town","subtitle":"Location","details":"Hyrule's capital market crowds beneath the castle walls with shops, games and gossip, its fountain square serving as the kingdom's crossroads.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/e/e7/OoT3D_Hyrule_Castle_Town.png/320px-OoT3D_Hyrule_Castle_Town.png"},{"name":"Hyrule Field","rarity":"epic","id":"hyrule-field","subtitle":"Location","details":"Rolling plains stretch between Hyrule's towns, ranches and frontiers, crossed by rivers, roads, Peahats at dawn and riders on the open grass.","image":"assets/sets/compress/zelda__hyrule-field.webp"},{"name":"Water Temple","rarity":"epic","id":"water-temple","subtitle":"Dungeon","details":"Beneath Lake Hylia, this submerged maze shifts its water through three levels, a Longshot gauntlet remembered for its keys and dark reflection.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/a/a4/OoT3D_Water_Temple.png/320px-OoT3D_Water_Temple.png"},{"name":"Stone Tower Temple","rarity":"epic","id":"stone-tower-temple","subtitle":"Dungeon","details":"Ikana's colossal temple flips the world upside down, turning floors into ceilings as light, mirrors and Elegy statues solve its inverted halls.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/d/d3/MM3D_Stone_Tower_Temple.png/320px-MM3D_Stone_Tower_Temple.png"},{"name":"Forsaken Fortress","rarity":"epic","id":"forsaken-fortress","subtitle":"Dungeon","details":"A pirate stronghold on the Great Sea, ringed by searchlights and cannons, where a giant bird carries captives to Ganondorf's prison tower.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/d/dd/TWWHD_Forsaken_Fortress.png/320px-TWWHD_Forsaken_Fortress.png"},{"name":"Forest Temple","rarity":"rare","id":"forest-temple","subtitle":"Dungeon","details":"Vines choke this ruined manor deep in the Sacred Forest Meadow, where twisted halls, Stalfos duels and four Poe Sisters guard the Hero's Bow.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/f/f0/OoT3D_Forest_Temple.png/320px-OoT3D_Forest_Temple.png"},{"name":"Spirit Temple","rarity":"rare","id":"spirit-temple","subtitle":"Dungeon","details":"Twin statues mark a colossal desert temple explored as both child and adult, crossing mirrors, sun blocks and the witches Twinrova at its heart.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/d/da/OoT3D_Spirit_Temple.png/320px-OoT3D_Spirit_Temple.png"},{"name":"Tower of the Gods","rarity":"rare","id":"tower-of-the-gods","subtitle":"Dungeon","details":"This tower rises from the Great Sea in ringing bells and flooded trials, testing the chosen hero before revealing a kingdom beneath the waves.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/a/a6/TWWHD_Tower_of_the_Gods.png/320px-TWWHD_Tower_of_the_Gods.png"},{"name":"Ancient Cistern","rarity":"rare","id":"ancient-cistern","subtitle":"Dungeon","details":"A serene, gilded cistern in Faron hides a cursed underworld of threads and undead below, where purity and corruption meet in one golden statue.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/c/c4/SSHD_Ancient_Cistern.png/320px-SSHD_Ancient_Cistern.png"},{"name":"Arbiter's Grounds","rarity":"rare","id":"arbiters-grounds","subtitle":"Dungeon","details":"A desert prison colosseum stands over execution grounds haunted by Stalfos and Poes, its Spinner rails leading to the Mirror of Twilight above.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/e/e6/TP_Arbiter%27s_Grounds.png/320px-TP_Arbiter%27s_Grounds.png"},{"name":"Snowpeak Ruins","rarity":"rare","id":"snowpeak-ruins","subtitle":"Dungeon","details":"A frozen manor in the Snowpeak mountains is home to a yeti couple, a cannonball arsenal and soup that strengthens with each gathered ingredient.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/c/c6/TP_Snowpeak_Ruins.png/320px-TP_Snowpeak_Ruins.png"},{"name":"City in the Sky","rarity":"rare","id":"city-in-the-sky","subtitle":"Dungeon","details":"Crumbling towers of the Oocca drift high above Hyrule, reached by cannon and crossed with Double Clawshots between fans, pillars and dragon fire.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/9/95/TPHD_City_in_the_Sky.png/320px-TPHD_City_in_the_Sky.png"},{"name":"Ganon's Tower","rarity":"rare","id":"ganons-tower","subtitle":"Dungeon","details":"A dark tower rises over the Dark World behind a barrier of stolen power, its gauntlet of bosses guarding the path to Ganon's final confrontation.","image":"https://cdn.wikimg.net/en/zeldawiki/images/4/4c/ALttP_Ganon%27s_Tower.png"},{"name":"Lake Hylia","rarity":"rare","id":"lake-hylia","subtitle":"Location","details":"Hyrule's great southern lake is fed by Zora's River, dotted with islands and a fishing pond, and hides the Water Temple beneath its deep waters.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/3/30/TP_Lake_Hylia.jpg/320px-TP_Lake_Hylia.jpg"},{"name":"Lon Lon Ranch","rarity":"rare","id":"lon-lon-ranch","subtitle":"Location","details":"A walled horse ranch at the heart of Hyrule Field, raising Cuccos, cows and prized horses, and bottling Lon Lon Milk behind its famous racetrack.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/7/75/OoT3D_Lon_Lon_Ranch.png/320px-OoT3D_Lon_Lon_Ranch.png"},{"name":"Hateno Village","rarity":"rare","id":"hateno-village","subtitle":"Location","details":"A peaceful farming village in East Necluda climbs terraced hills past a dye shop, an inn and an ancient tech lab above fields and paddies below.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/1/10/BotW_Hateno_Village.png/320px-BotW_Hateno_Village.png"},{"name":"Tarrey Town","rarity":"rare","id":"tarrey-town","subtitle":"Location","details":"Built from bare rock on a Lake Akkala mesa, this town grows house by house as workers, merchants and couples arrive from across all of Hyrule.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/7/77/TotK_Tarrey_Town.png/512px-TotK_Tarrey_Town.png"},{"name":"Dragon Roost Island","rarity":"rare","id":"dragon-roost-island","subtitle":"Location","details":"A volcanic Great Sea island shelters the Rito in cavern homes beneath the sky spirit Valoo, where fledglings earn wings in the roosting caverns.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/6/6f/TWW_Dragon_Roost_Island.png/320px-TWW_Dragon_Roost_Island.png"},{"name":"Lost Woods","rarity":"rare","id":"lost-woods","subtitle":"Location","details":"A maze-like forest warps travellers who take a wrong turn back to its edge, while the ready find sacred meadows, skull children and hidden grottos.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/a/ac/TotK_Lost_Woods.png/512px-TotK_Lost_Woods.png"},{"name":"Gerudo Town","rarity":"rare","id":"gerudo-town","subtitle":"Location","details":"A desert city of markets, training grounds and a palace court, ruled by the Gerudo chief and closed to voe without a disguise of veil and silk.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/0/03/BotW_Gerudo_Town.png/320px-BotW_Gerudo_Town.png"},{"name":"Lanayru","rarity":"rare","id":"lanayru","subtitle":"Location","details":"Hyrule's eastern province spans desert canyons, wetlands, mines and coast, named for the dragon Lanayru and layered with ancient robot ruins.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/d/d4/BotW_Lanayru.png/320px-BotW_Lanayru.png"},{"name":"Fire Temple","rarity":"uncommon","id":"fire-temple","subtitle":"Dungeon","details":"Inside Death Mountain Crater, lava channels and rolling boulders cage imprisoned Gorons, guarded by the ancient dragon Volvagia in its deepest hall.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/4/41/OoT3D_Fire_Temple.png/320px-OoT3D_Fire_Temple.png"},{"name":"Shadow Temple","rarity":"uncommon","id":"shadow-temple","subtitle":"Dungeon","details":"Below Kakariko's graveyard, this grisly Sheikah temple hides truth behind illusions, guillotines, dead hands and a boat ride across the darkness.","image":"assets/sets/compress/zelda__shadow-temple.webp"},{"name":"Great Bay Temple","rarity":"uncommon","id":"great-bay-temple","subtitle":"Dungeon","details":"A mechanical ocean temple off Great Bay Coast drives pumps, pipes and channels in every direction, its reversed flows guarded by the fish Gyorg.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/c/c7/MM3D_Great_Bay_Temple_Exterior.png/320px-MM3D_Great_Bay_Temple_Exterior.png"},{"name":"Earth Temple","rarity":"uncommon","id":"earth-temple","subtitle":"Dungeon","details":"On Headstone Island, undead halls and mirrors test a sage's prayers, as light is carried through darkness to sustain the Master Sword's power.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/8/8f/TWWHD_Earth_Temple.png/320px-TWWHD_Earth_Temple.png"},{"name":"Wind Temple","rarity":"uncommon","id":"wind-temple","subtitle":"Dungeon","details":"Gale Isle's temple runs on rising winds, giant fans and springboards, where a Wind Sage's prayer keeps the Master Sword shining across the sea.","image":"https://www.zeldadungeon.net/wiki/images/5/53/Wind-Temple-1F.jpg"},{"name":"Goron Mines","rarity":"uncommon","id":"goron-mines","subtitle":"Dungeon","details":"Magnetic ceilings and lava caverns fill the Goron elders' iron mines inside Death Mountain, crossed by Iron Boots, arrows and slow-moving lava rock.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/7/7c/TPHD_Goron_Mines.png/320px-TPHD_Goron_Mines.png"},{"name":"Lakebed Temple","rarity":"uncommon","id":"lakebed-temple","subtitle":"Dungeon","details":"A vast waterworks rests on the bed of Lake Hylia, turning a central staircase and waterwheels to route the flow toward the lurking Morpheel below.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/d/d2/TPHD_Lakebed_Temple.png/320px-TPHD_Lakebed_Temple.png"},{"name":"Lanayru Mining Facility","rarity":"uncommon","id":"lanayru-mining-facility","subtitle":"Dungeon","details":"An ancient refinery buried in Lanayru Desert springs back to life in Timeshift bubbles, its carts, conveyors and robots shifting between eras.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/9/99/SS_Lanayru_Mining_Facility.png/320px-SS_Lanayru_Mining_Facility.png"},{"name":"Sandship","rarity":"uncommon","id":"sandship","subtitle":"Dungeon","details":"A pirate ship sails the sea of sand in Lanayru, crewed by ancient robots and steered through time to face the kraken sealed within its hold.","image":"https://cdn.wikimg.net/en/zeldawiki/images/9/9d/SS_Sandship.png"},{"name":"Divine Beast Vah Ruta","rarity":"uncommon","id":"divine-beast-vah-ruta","subtitle":"Dungeon","details":"The elephant-shaped Divine Beast floods Zora's Domain from East Reservoir Lake, sending endless rain from its raised trunk and waterwheel halls.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/9/90/BotW_Divine_Beast_Vah_Ruta.png/512px-BotW_Divine_Beast_Vah_Ruta.png"},{"name":"Divine Beast Vah Medoh","rarity":"uncommon","id":"divine-beast-vah-medoh","subtitle":"Dungeon","details":"The eagle-shaped Divine Beast circles Rito Village behind a shimmering shield, its cannons and tilting wings guarding the skies over Lake Totori.","image":"https://cdn.wikimg.net/en/zeldawiki/images/4/4f/BotW_Divine_Beast_Vah_Medoh.png"},{"name":"Divine Beast Vah Rudania","rarity":"uncommon","id":"divine-beast-vah-rudania","subtitle":"Dungeon","details":"The lizard-shaped Divine Beast crawls across Death Mountain's slopes in a shower of volcanic rock, driving Gorons from their mines and hot springs.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/d/d5/BotW_Divine_Beast_Vah_Rudania_%28Dungeon%29.png/320px-BotW_Divine_Beast_Vah_Rudania_%28Dungeon%29.png"},{"name":"Divine Beast Vah Naboris","rarity":"uncommon","id":"divine-beast-vah-naboris","subtitle":"Dungeon","details":"The camel-shaped Divine Beast stalks the Gerudo Desert inside swirling sandstorms, calling lightning down on any who approach its rotating halls.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/2/2b/BotW_Divine_Beast_Vah_Naboris.png/512px-BotW_Divine_Beast_Vah_Naboris.png"},{"name":"Lookout Landing","rarity":"uncommon","id":"lookout-landing","subtitle":"Location","details":"A fortified research outpost rises below Hyrule Castle, gathering survey teams, sky watchers and travellers around its emergency shelter and well.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/9/94/TotK_Lookout_Landing.png/320px-TotK_Lookout_Landing.png"},{"name":"Lurelin Village","rarity":"uncommon","id":"lurelin-village","subtitle":"Location","details":"Palm huts and fishing boats line this laid-back village on the Faron Sea coast, where villagers trade in fish, bananas and seaside treasure alike.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/f/f3/BotW_Lurelin_Village.png/320px-BotW_Lurelin_Village.png"},{"name":"Rito Village","rarity":"uncommon","id":"rito-village","subtitle":"Location","details":"Wooden homes spiral around a rock spire in Lake Totori, joined by rope bridges, where Rito warriors, fledglings and bards share the mountain wind.","image":"assets/sets/compress/zelda__rito-village.webp"},{"name":"Goron City","rarity":"uncommon","id":"goron-city","subtitle":"Location","details":"A mining city carved into Death Mountain's slopes rings a central forge and hot springs, home to rock-eating Gorons, mine carts and fireproof wares.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/3/38/TotK_Goron_City.png/320px-TotK_Goron_City.png"},{"name":"Outset Island","rarity":"uncommon","id":"outset-island","subtitle":"Location","details":"A small, peaceful Great Sea island of lookout towers and two hills, where a grandmother's soup and a birthday tunic begin a hero's journey in green.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/9/91/TWWHD_Outset_Island.png/320px-TWWHD_Outset_Island.png"},{"name":"Romani Ranch","rarity":"uncommon","id":"romani-ranch","subtitle":"Location","details":"Termina's ranch supplies Chateau Romani milk and raises dogs, Cuccos and horses, while a young keeper guards the barn against a nighttime threat.","image":"assets/sets/compress/zelda__romani-ranch.webp"},{"name":"Ikana Canyon","rarity":"uncommon","id":"ikana-canyon","subtitle":"Location","details":"A haunted canyon holds the Ancient Castle, a dried well and a kingdom of the dead beneath Stone Tower, where Gibdos and Garos still keep old grudges.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/a/a7/MM_Ikana_Canyon.png/320px-MM_Ikana_Canyon.png"},{"name":"Faron Woods","rarity":"uncommon","id":"faron-woods","subtitle":"Location","details":"Deep southern woods hide Kikwi burrows, sacred springs and ancient temples beneath towering trees, watched over by the water dragon Faron herself.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/6/6e/BotW_Faron_Woods.png/320px-BotW_Faron_Woods.png"},{"name":"Eldin Volcano","rarity":"uncommon","id":"eldin-volcano","subtitle":"Location","details":"A fiery region of lava rivers and bombable tunnels is worked by Mogma treasure hunters, rising from forest foothills to the Earth Temple's gates.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/3/35/SSHD_Eldin_Volcano.png/320px-SSHD_Eldin_Volcano.png"},{"name":"The Sky","rarity":"uncommon","id":"the-sky","subtitle":"Location","details":"An ocean of clouds stretches above the Surface, dotted with floating isles, skydiving knights, pumpkin soup and portals opened by ancient beacons.","image":"https://cdn.wikimg.net/en/zeldawiki/images/6/69/SS_Thunderhead.png"},{"name":"Korok Forest","rarity":"uncommon","id":"korok-forest","subtitle":"Location","details":"A misty clearing deep in the Lost Woods gathers Koroks around the Great Deku Tree, where the Master Sword rests in its stone pedestal once more.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/a/a2/BotW_Korok_Forest.png/320px-BotW_Korok_Forest.png"},{"name":"Sealed Temple","rarity":"uncommon","id":"sealed-temple","subtitle":"Location","details":"An ancient temple at the bottom of the Sealed Grounds anchors a great spiral prison, watched by an elderly keeper and the Goddess's harp songs.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/c/c4/SSHD_Sealed_Temple.png/320px-SSHD_Sealed_Temple.png"},{"name":"Woodfall Temple","rarity":"common","id":"woodfall-temple","subtitle":"Dungeon","details":"A poison-swamped temple rises from the Southern Swamp's waters on Deku flowers and wooden bridges, guarding a giant masked jungle warrior within.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/5/57/MM3D_Woodfall_Temple_Entrance.png/320px-MM3D_Woodfall_Temple_Entrance.png"},{"name":"Snowhead Temple","rarity":"common","id":"snowhead-temple","subtitle":"Dungeon","details":"An icy temple in Termina's frozen north is built around a towering central pillar of ice, fire and Goron punches rising through its frozen floors.","image":"assets/sets/compress/zelda__snowhead-temple.webp"},{"name":"Dragon Roost Cavern","rarity":"common","id":"dragon-roost-cavern","subtitle":"Dungeon","details":"Lava channels and bomb flowers fill the cavern inside Dragon Roost Island, where a captured dragon's tail hangs above the first Great Sea dungeon.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/9/91/TWWHD_Dragon_Roost_Cavern.png/320px-TWWHD_Dragon_Roost_Cavern.png"},{"name":"Forbidden Woods","rarity":"common","id":"forbidden-woods","subtitle":"Dungeon","details":"An overgrown island forest is hollowed into a dungeon by a giant parasite plant, its Deku Leaf glides crossing gaps between thorny, windblown halls.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/7/71/TWWHD_Forbidden_Woods.png/320px-TWWHD_Forbidden_Woods.png"},{"name":"Skyview Temple","rarity":"common","id":"skyview-temple","subtitle":"Dungeon","details":"Moss, vines and ancient stone cover this temple deep in Faron Woods, where Stalfos, a Staldra and a first glimpse of a demon lord await below.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/e/e0/SSHD_Skyview_Temple.png/320px-SSHD_Skyview_Temple.png"},{"name":"Sky Keep","rarity":"common","id":"sky-keep","subtitle":"Dungeon","details":"Beneath Skyloft, sliding rooms rearrange this temple around three sacred flames' prize, holding the Triforce pieces in trials of every goddess.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/6/69/SS_Sky_Keep.png/320px-SS_Sky_Keep.png"},{"name":"Eastern Palace","rarity":"common","id":"eastern-palace","subtitle":"Dungeon","details":"A palace at Hyrule's desert edge guards the Pendant of Courage behind Armos statues, ball-and-chain soldiers and the hero's first great bow trial.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/3/30/ALttP_Eastern_Palace_Artwork.png/320px-ALttP_Eastern_Palace_Artwork.png"},{"name":"Turtle Rock","rarity":"common","id":"turtle-rock","subtitle":"Dungeon","details":"A lava-filled dungeon shaped like a turtle appears on Death Mountain and Koholint alike, crossed by pipe mazes, fire bars and a magic rod's blaze.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/2/2e/LANS_Turtle_Rock.png/320px-LANS_Turtle_Rock.png"},{"name":"The Eagle","rarity":"common","id":"the-eagle","subtitle":"Dungeon","details":"Level 1 hides an eagle-shaped labyrinth beneath a dead tree on a lake isle, the very first dungeon, guarding a bow, a boomerang and a Triforce shard.","image":"https://cdn.wikimg.net/en/zeldawiki/images/2/25/TLoZ_Level-1_Entrance.png"},{"name":"Mabe Village","rarity":"common","id":"mabe-village","subtitle":"Location","details":"A sleepy village on Koholint Island centres on a rooster weathervane, a trendy game and the homes of Marin, Tarin and a chained pet called BowWow.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/6/6e/LANS_Mabe_Village.png/512px-LANS_Mabe_Village.png"},{"name":"Ordon Village","rarity":"common","id":"ordon-village","subtitle":"Location","details":"A farming and ranching village in Ordona Province raises pumpkins, goats and horses beside a spring, at the southern edge of Hyrule's wild lands.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/e/ea/Ordon_Village.jpg/320px-Ordon_Village.jpg"},{"name":"Horon Village","rarity":"common","id":"horon-village","subtitle":"Location","details":"Holodrum's central village wraps around the great Maku Tree and its clock tower, changing its shops, paths and people with every turn of the seasons.","image":"https://www.zeldadungeon.net/wiki/images/9/98/Horon-Village-Fountain.png"},{"name":"Hytopia","rarity":"common","id":"hytopia","subtitle":"Location","details":"A fashion-fixated kingdom sends trios of heroes from its castle town into the Drablands, where Madame Couture's outfits grant powers beyond style.","image":"https://cdn.wikimg.net/en/zeldawiki/images/7/75/TFH_Hytopia.png"},{"name":"Lorule","rarity":"common","id":"lorule","subtitle":"Location","details":"A fractured mirror kingdom mirrors Hyrule with a crumbling castle, inverted Triforce and desperate court, its fissures linking two darkening worlds.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/a/a3/ALBW_Lorule_Castle_Exterior.png/320px-ALBW_Lorule_Castle_Exterior.png"},{"name":"Koholint Island","rarity":"common","id":"koholint-island","subtitle":"Location","details":"A dream island rises beneath the Wind Fish's egg on Mt. Tamaranch, its villages, swamps and deserts mapped by a chain of eight instrument dungeons.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/a/a4/LANS_Ending_Koholint_Island.png/320px-LANS_Ending_Koholint_Island.png"},{"name":"Termina Field","rarity":"common","id":"termina-field","subtitle":"Location","details":"Grassy plains ring Clock Town in four directions, opening toward swamp, mountain, ocean and canyon frontiers guarded by fences, posts and strange foes.","image":"assets/sets/compress/zelda__termina-field.webp"},{"name":"The Great Sea","rarity":"common","id":"the-great-sea","subtitle":"Location","details":"A vast ocean covers flooded Hyrule with island towns, towers, reefs and treasure charts, crossed by talking boats, cyclones and charted trade winds.","image":"https://www.zeldadungeon.net/wiki/images/3/33/Great-Sea-Theme.png"},{"name":"Gerudo Fortress","rarity":"common","id":"gerudo-fortress","subtitle":"Location","details":"A thieves' stronghold in Gerudo Valley hides prison cells, horseback archery and a membership card behind guards with no patience for intruders.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/b/bd/OoT_Gerudo%27s_Fortress.png/512px-OoT_Gerudo%27s_Fortress.png"},{"name":"Zora's River","rarity":"common","id":"zoras-river","subtitle":"Location","details":"The river runs from Zora's Domain through gorges and waterfalls down to Lake Hylia, carrying rafts, Cuccos and the kingdom's clearest cold water.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/7/79/EoW_Zora_River.png/512px-EoW_Zora_River.png"},{"name":"Akkala Citadel","rarity":"common","id":"akkala-citadel","subtitle":"Location","details":"Ruined walls crown a hilltop fortress in Akkala, where Hyrule made a stand against the Calamity amid cannons, guardians and broken watch towers.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/2/24/BotW_Akkala_Citadel_Ruins.png/512px-BotW_Akkala_Citadel_Ruins.png"},{"name":"Satori Mountain","rarity":"common","id":"satori-mountain","subtitle":"Location","details":"A cherry-blossomed peak in Hyrule Ridge glows under the Lord of the Mountain, its slopes rich with herbs, apples and creatures gathered by moonlight.","image":"assets/sets/compress/zelda__satori-mountain.webp"},{"name":"Sealed Grounds","rarity":"common","id":"sealed-grounds","subtitle":"Location","details":"A vast spiralled pit descends behind the Sealed Temple, where an imprisoned evil strains upward against a seal renewed by prayer, song and courage.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/7/72/SSHD_Sealed_Grounds.png/320px-SSHD_Sealed_Grounds.png"},{"name":"Hyrule Town","rarity":"common","id":"hyrule-town","subtitle":"Location","details":"A castle town capital built for the annual Picori Festival fills with stalls, kinstones and swordplay crowds in a Hyrule shrunk to Minish scale.","image":"https://cdn.wikimg.net/en/zeldawiki/images/d/d6/TMC_Hyrule_Town.png"},{"name":"Lynna City","rarity":"common","id":"lynna-city","subtitle":"Location","details":"Labrynna's city exists in both past and present ages, its Maku Tree, shops and Ambi's Tower changing across centuries linked by the Harp of Ages.","image":"https://cdn.wikimg.net/en/zeldawiki/images/a/a2/OoA_Lynna_City.png"},{"name":"Suthorn Village","rarity":"common","id":"suthorn-village","subtitle":"Location","details":"A village on Hyrule's southern prairie sits near the Suthorn Ruins and a forest of echoes, where farmers first report rifts opening across the land.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/e/e9/EoW_Suthorn_Village.png/320px-EoW_Suthorn_Village.png"}]});
